from datetime import date; from decimal import Decimal; from uuid import uuid4; import pytest; from httpx import AsyncClient; from sqlalchemy.ext.asyncio import AsyncSession; from src.extraction import ClassificationStatus, TransactionDirection; from src.extraction.orm.layer2 import AtomicTransaction; from src.extraction.orm.layer3 import TransactionClassification; from src.identity import User; pytestmark = pytest.mark.asyncio
async def _create_classification(db: AsyncSession, user_id, *, tags, account_id=None, confidence=70, status=ClassificationStatus.DRAFT): atomic = AtomicTransaction(user_id=user_id, txn_date=date(2024, 6, 1), amount=Decimal('1.23'), direction=TransactionDirection.OUT, description='Edge txn', currency='SGD', dedup_hash=f'edge-{uuid4()}', source_documents=[]); db.add(atomic); await db.flush(); from src.extraction import RuleType; from src.extraction.orm.layer3 import ClassificationRule; rule = ClassificationRule(user_id=user_id, version_number=1, effective_date=date(2024, 1, 1), rule_name=f'r-{uuid4()}', rule_type=RuleType.KEYWORD_MATCH, rule_config={'keywords': ['edge']}, created_by=user_id); db.add(rule); await db.flush(); classification = TransactionClassification(atomic_txn_id=atomic.id, rule_version_id=rule.id, confidence_score=confidence, status=status, tags=tags, account_id=account_id); db.add(classification); await db.flush(); return classification
async def test_classification_tags_not_dict_uses_account_id(client: AsyncClient, db: AsyncSession, test_user: User): from src.ledger import Account, AccountType; acct = Account(id=uuid4(), user_id=test_user.id, name='Test acct', type=AccountType.ASSET, currency='SGD'); db.add(acct); await db.flush(); cls = await _create_classification(db, test_user.id, tags='not-a-dict', account_id=acct.id); await db.commit(); resp = await client.get('/statements/classification-suggestions'); assert resp.status_code == 200; items = resp.json()['items']; found = [i for i in items if i['suggestion_id'] == str(cls.id)]; assert found, items; assert found[0]['suggested_category_or_match'] == str(acct.id)
